from pathlib import Path


def patch(path,replacements):
    p=Path(path); s=p.read_text()
    for old,new,count in replacements:
        n=s.count(old)
        if n!=count:
            raise SystemExit(f'{path}: expected {count}, got {n}: {old[:160]!r}')
        s=s.replace(old,new,count)
    p.write_text(s)

